// Extrae el texto de la respuesta de DeepSeek
const response = $input.first().json;
const choice = response.choices?.[0];
const text = choice?.message?.content || 'Lo siento, no pude procesar tu mensaje.';

return {
  json: {
    text,
    action: null,
    usage: response.usage
  }
};
